insert into manufacturers (slug, name, country, website_url, description_ko, description_en, is_active, sort_order)
values ('dynaset', 'DYNASET', 'Finland', 'https://dynaset.com', '다이나셋(DYNASET)은 유압 발전기, 파워 세척 유니트 및 콤프레샤 분야의 글로벌 선두 제조업체입니다. 이동식 기계, 차량, 선박의 유압 동력을 전기, 고압 워터, 압축공기, 마그넷(자석), 진동, 파워 부스팅 및 진공으로 변환하는 유압 장비를 생산합니다.', 'DYNASET is a leading global manufacturer of hydraulic generators, power washing units and compressors. Its hydraulic equipment converts the hydraulic power of mobile machinery, vehicles and vessels into electricity, high-pressure water, compressed air, magnet power, vibration, power boosting and vacuum.', true, 10)
on conflict (slug) do update set name = excluded.name, country = excluded.country, website_url = excluded.website_url,
  description_ko = excluded.description_ko, description_en = excluded.description_en, updated_at = now();

insert into manufacturers (slug, name, country, website_url, description_ko, description_en, is_active, sort_order)
values ('euroswitch', 'Euroswitch', 'Italy', 'https://www.euroswitch.it', 'Euroswitch는 이탈리아 살레 마라시노(Sale Marasino)에 본사를 둔 센서 전문 제조사로, 압력·레벨·온도 스위치 및 센서를 설계·생산합니다. 전자기식(리드) 플로트 레벨 스위치부터 저항식·아날로그 4-20mA 레벨 센서까지 폭넓은 라인업을 보유하고 있습니다.', 'Euroswitch is an Italian sensor manufacturer based in Sale Marasino (BS), designing and producing pressure, level and temperature switches and sensors, from electromagnetic (reed) float level switches to resistive and analog 4-20 mA level sensors.', true, 20)
on conflict (slug) do update set name = excluded.name, country = excluded.country, website_url = excluded.website_url,
  description_ko = excluded.description_ko, description_en = excluded.description_en, updated_at = now();

insert into manufacturers (slug, name, country, website_url, description_ko, description_en, is_active, sort_order)
values ('gemels', 'GEMELS S.p.A.', 'Italy', 'https://www.gemels.com', 'GEMELS S.p.A.는 1969년 설립된 이탈리아의 볼 밸브·퀵 커플링 전문 제조사로, 1/4인치부터 42인치까지의 제품을 생산하며 유압·산업 분야의 세계적 선도 기업입니다. 2010년부터는 오일&가스 분야와 전동화(Green Power) 제품군으로 사업을 확장하고 있습니다.', 'Founded in 1969, GEMELS S.p.A. is an Italian manufacturer specializing in ball valves and quick couplings from 1/4" up to 42", and a world leader in the hydraulic and industrial fields. Since 2010 it has also expanded into Oil & Gas valves and Green Power electrification products.', true, 30)
on conflict (slug) do update set name = excluded.name, country = excluded.country, website_url = excluded.website_url,
  description_ko = excluded.description_ko, description_en = excluded.description_en, updated_at = now();

insert into manufacturers (slug, name, country, website_url, description_ko, description_en, is_active, sort_order)
values ('moveco', 'MOVECO SRL', 'Italy', 'https://www.movecosrl.com', 'MOVECO는 이탈리아 그리냐스코에 본사를 둔 헬리컬 로터리 액추에이터 및 유압 매니폴드 전문 제조사로, 15년 이상 고소작업대·크레인 등 리프팅 분야의 주요 OEM에 맞춤형 유압 솔루션을 공급하고 있습니다. HydraForce의 이탈리아 공식 디스트리뷰터이며 UNI EN ISO 9001:2015 인증을 보유하고 있습니다.', 'MOVECO SRL, based in Grignasco, Italy, specializes in helical rotary actuators and hydraulic manifolds, supplying customized hydraulic solutions to major aerial platform and lifting OEMs for over 15 years. The company is the official Italian distributor of HydraForce and is certified to UNI EN ISO 9001:2015.', true, 40)
on conflict (slug) do update set name = excluded.name, country = excluded.country, website_url = excluded.website_url,
  description_ko = excluded.description_ko, description_en = excluded.description_en, updated_at = now();

