values ('euroswitch-analog-level-sensors', '아날로그 레벨 센서 (4-20mA)', 'Analog Level Sensors (4-20 mA)', '4-20mA 아날로그 출력으로 유체 레벨을 연속 측정하는 레벨 트랜스미터입니다. 일부 모델은 온도 측정 및 프로그래머블 디지털 출력을 함께 제공합니다.', 'Level transmitters providing continuous 4-20 mA analog output. Some models also provide temperature measurement and programmable digital outputs.', (select id from business_areas where slug = 'hydraulic-engineering'), 70, '[{"key": "output_signal", "labelKo": "출력 신호", "labelEn": "Output signal", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "digital_outputs", "labelKo": "디지털 출력", "labelEn": "Digital outputs", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "supply_voltage", "labelKo": "공급 전압", "labelEn": "Supply voltage", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "fixing", "labelKo": "고정 방식", "labelEn": "Fixing", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "stem_material", "labelKo": "스템 재질", "labelEn": "Stem material", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "float_material", "labelKo": "플로트 재질", "labelEn": "Float material", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "length_range", "labelKo": "길이 범위", "labelEn": "Length range", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": true}, {"key": "resolution_pitch", "labelKo": "분해능(피치)", "labelEn": "Resolution (pitch)", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "protection_rating", "labelKo": "보호 등급", "labelEn": "Protection degree", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "operating_temp", "labelKo": "사용 온도", "labelEn": "Working temperature", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "m