insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-capacitive-level-sensors', '정전용량식 레벨 센서', 'Capacitive Level Sensors', '가동부 없이 정전용량 방식으로 유체 유무를 감지하는 전자식 레벨 센서입니다. 황동 바디 G1/2 나사 결합형으로 오일, 수용성 절삭유, 경유 등의 레벨 감지에 사용됩니다.', 'Electronic capacitive level sensors with no moving parts, in a brass G1/2 threaded body, used to detect the presence of oils, water-based coolants, water and diesel.', (select id from business_areas where slug = 'hydraulic-engineering'), 80, '[{"key": "output_signal", "labelKo": "출력 신호", "labelEn": "Output signal", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "supply_voltage", "labelKo": "공급 전압", "labelEn": "Supply voltage", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "ntc_included", "labelKo": "NTC 온도센서 내장", "labelEn": "NTC thermistor included", "dataType": "boolean", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "working_pressure", "labelKo": "사용 압력", "labelEn": "Working pressure", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body material", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "접속 규격", "labelEn": "Process connection", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical connection", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "protection_rating", "labelKo": "보호 등급", "labelEn": "Protection degree", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": true}, {"key": "ambient_temp", "labelKo": "주위 온도", "labelEn": "Ambient temperature", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "fluid_temp", "labelKo": "유체 온도", "labelEn": "Fluid temperature", "dataType": "text", "requi