insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-clogging-indicators', '차압 인디케이터 (필터 막힘 감지)', 'Differential Clogging Indicators', '유압 필터의 막힘을 감지하는 차압 인디케이터입니다. 필터 전후의 차압(ΔP)이 설정값을 넘으면 시각·전기·전자 신호로 알려주며, 4-20mA/MODBUS/IO-Link 출력의 전자식 차압 트랜스미터도 포함합니다.', 'Differential pressure indicators used to detect filter clogging in hydraulic systems. When the differential pressure across the filter exceeds the set value, they provide visual, electrical or electronic indication; electronic differential transmitters with 4-20 mA, MODBUS or IO-Link output are included.', (select id from business_areas where slug = 'hydraulic-engineering'), 90, '[{"key": "indicator_type", "labelKo": "인디케이터 방식", "labelEn": "Indicator Type", "dataType": "select", "options": [{"value": "electrical", "labelKo": "전기식 (접점)", "labelEn": "Electrical (contacts)"}, {"value": "visual", "labelKo": "시각식", "labelEn": "Visual (optical)"}, {"value": "electronic", "labelKo": "전자식", "labelEn": "Electronic"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "differential_pressure_range", "labelKo": "차압 설정 범위", "labelEn": "Differential Pressure Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "max_line_pressure_bar", "labelKo": "최대 라인 압력 (P1=P2)", "labelEn": "Max Line Pressure (P1=P2)", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "output_type", "labelKo": "출력 형식", "labelEn": "Output Type", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class (IP)", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "media_temp_range", "labelKo": "유체 온도 범위", "labelEn": "Media Temperature Range", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "medium", "labelKo": "적용 유체", "labelEn": "Medium", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}]'::jsonb)
