insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-electromechanical-reserve-sensors', '전기기계식 리저브 레벨 센서', 'Electromechanical Reserve Level Sensors', '은도금 접점을 사용하는 전기기계식 잔량(리저브) 레벨 센서로, 안전 초저전압 회로나 축전지 회로에 적합합니다. 연료 탱크의 잔량 경고용으로 주로 사용됩니다.', 'Electromechanical reserve level sensors with silver-plated contacts, suitable for very low-voltage safety circuits or electric accumulators, typically used for fuel tank reserve warning.', (select id from business_areas where slug = 'hydraulic-engineering'), 100, '[{"key": "media", "labelKo": "적용 유체", "labelEn": "Media", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "fixing", "labelKo": "고정 방식", "labelEn": "Fixing", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "stem_material", "labelKo": "스템 재질", "labelEn": "Stem material", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "float_material", "labelKo": "플로트 재질", "labelEn": "Float material", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact type", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "max_switching_power_w", "labelKo": "최대 개폐 용량", "labelEn": "Max switching capacity", "dataType": "unit_value", "unit": "W", "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "max_switching_current_a", "labelKo": "최대 개폐 전류", "labelEn": "Max switching current", "dataType": "unit_value", "unit": "A", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "max_switching_voltage", "labelKo": "최대 개폐 전압", "labelEn": "Max switching voltage", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "min_specific_gravity", "labelKo": "최소 유체 비중", "labelEn": "Min fluid specific gravity", "dataType": "number", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "operating_temp", "la