insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-float-level-switches', '플로트 레벨 스위치', 'Float Level Switches', '마그네틱 플로트와 리드 접점을 이용한 전자기식 온/오프 레벨 스위치입니다. 수직·측면 장착, 다양한 재질(폴리프로필렌, 나일론, 황동, 스테인리스)과 접속 규격으로 물, 오일, 연료 등 다양한 유체의 레벨 감지에 사용됩니다.', 'Electromagnetic on/off level switches using a magnetic float and reed contact. Available in vertical or lateral mounting with various materials (polypropylene, nylon, brass, stainless steel) and connections for water, oils, fuels and other fluids.', (select id from business_areas where slug = 'hydraulic-engineering'), 110, '[{"key": "mounting", "labelKo": "장착 방식", "labelEn": "Mounting", "dataType": "select", "options": [{"value": "vertical", "labelKo": "수직", "labelEn": "Vertical"}, {"value": "lateral", "labelKo": "측면(수평)", "labelEn": "Lateral (horizontal)"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "process_connection", "labelKo": "접속 규격", "labelEn": "Process connection", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "stem_material", "labelKo": "스템 재질", "labelEn": "Stem material", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "float_material", "labelKo": "플로트 재질", "labelEn": "Float material", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact type", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "max_switching_power_w", "labelKo": "최대 개폐 용량", "labelEn": "Max switching capacity", "dataType": "unit_value", "unit": "W", "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "max_switching_current_a", "labelKo": "최대 개폐 전류", "labelEn": "Max switching current", "dataType": "unit_value", "unit": "A", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "max_switching_voltage", "labelKo": "최대 개폐 전압", "labelEn": "Max switching voltage", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "min_specific_gravity", "labelKo": "최소 유체 비중", "labelEn": "Min fluid specific gravity", "dataType": "number", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "operating_temp", "labelKo": "사용 온도", "labelEn": "Working temperature", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "media", "labelKo": "적용 유체", "labelEn": "Media", "dataType": "text", "required": false, "sortOrder": 11, "showInCardTeaser": false}, {"key": "length_options", "labelKo": "길이 옵션", "labelEn": "Length options", "dataType": "text", "required": false, "sortOrder": 12, "showInCardTeaser": false}]'::jsonb)
