insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-pressure-switches', '압력 스위치', 'Pressure Switches', '다이어프램 또는 피스톤 방식의 기계식 압력 스위치입니다. 설정 압력 도달 시 전기 접점(NO/NC/SPDT)이 개폐되며, 유압·공압·산업기계·차량 분야에 사용됩니다.', 'Mechanical pressure switches with diaphragm or piston sensing element. Electric contacts (NO/NC/SPDT) switch when the set pressure is reached; used in hydraulics, pneumatics, industrial machinery and vehicles.', (select id from business_areas where slug = 'hydraulic-engineering'), 120, '[{"key": "setting_range", "labelKo": "설정 압력 범위", "labelEn": "Setting Range", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_working_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "overpressure_limit_bar", "labelKo": "최대 안전 압력", "labelEn": "Overpressure Limit", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact Type", "dataType": "select", "options": [{"value": "spst_no", "labelKo": "SPST 상시 개방(NO)", "labelEn": "SPST Normally Open (NO)"}, {"value": "spst_no_or_nc", "labelKo": "SPST NO 또는 NC", "labelEn": "SPST NO or NC"}, {"value": "spdt", "labelKo": "SPDT (절환 접점)", "labelEn": "SPDT (changeover)"}, {"value": "dual_spdt", "labelKo": "이중 마이크로스위치", "labelEn": "Double microswitch"}, {"value": "reed_spst", "labelKo": "리드 SPST", "labelEn": "Reed SPST"}, {"value": "spst_nc_parallel_no_series", "labelKo": "압력+온도 복합 접점", "labelEn": "Combined pressure + temperature contacts"}], "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_switching_voltage", "labelKo": "최대 개폐 전압", "labelEn": "Max Switching Voltage", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "sensing_element", "labelKo": "감지 방식", "labelEn": "Sensing Element", "dataType": "select", "options": [{"value": "diaphragm", "labelKo": "다이어프램", "labelEn": "Diaphragm"}, {"value": "piston", "labelKo": "피스톤", "labelEn": "Piston"}, {"value": "diaphragm_or_piston", "labelKo": "다이어프램/피스톤", "labelEn": "Diaphragm or piston"}], "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class (IP)", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "max_media_temp_c", "labelKo": "최대 유체 온도", "labelEn": "Max Media Temperature", "dataType": "unit_value", "unit": "°C", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}]'::jsonb)
