insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-pressure-transmitters', '압력 트랜스미터 / 전자식 압력 스위치', 'Pressure Transmitters / Electronic Pressure Switches', '세라믹 측정 셀 기반의 압력 트랜스미터와 전자식 압력 스위치입니다. 4-20mA·전압 아날로그 출력 또는 프로그래머블 PNP 디지털 출력을 제공하며, 유압·공압·프로세스 산업에 적합합니다.', 'Pressure transmitters and electronic pressure switches based on a ceramic sensing cell. Available with 4-20 mA or voltage analogue output, or programmable PNP digital outputs, for hydraulic, pneumatic and process industry applications.', (select id from business_areas where slug = 'hydraulic-engineering'), 130, '[{"key": "measuring_range", "labelKo": "측정 범위", "labelEn": "Measuring Range", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_range_bar", "labelKo": "최대 측정 범위 (풀스케일)", "labelEn": "Max Range (full scale)", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "output_signal", "labelKo": "출력 신호", "labelEn": "Output Signal", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "supply_voltage", "labelKo": "공급 전압", "labelEn": "Supply Voltage", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "accuracy", "labelKo": "정확도", "labelEn": "Accuracy", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical Connection", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class (IP)", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "response_time", "labelKo": "응답 시간", "labelEn": "Response Time", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "media_temp_range", "labelKo": "유체 온도 범위", "labelEn": "Media Temperature Range", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}]'::jsonb)
