values ('euroswitch-reed-position-sensors', '리드 위치 센서', 'Reed Position Sensors', '자석 접근을 리드 접점으로 감지하는 소형 위치 센서입니다. M8x1.25 양극산화 알루미늄 하우징으로 레벨 시스템의 위치 검출 등에 사용됩니다.', 'Compact position sensors detecting magnet proximity with a reed contact, in an M8x1.25 anodized aluminum housing.', (select id from business_areas where slug = 'hydraulic-engineering'), 140, '[{"key": "stem_material", "labelKo": "하우징 재질", "labelEn": "Housing material", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical connection", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact type", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_switching_power_w", "labelKo": "최대 개폐 용량", "labelEn": "Max switching capacity", "dataType": "unit_value", "unit": "W", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_switching_current_a", "labelKo": "최대 개폐 전류", "labelEn": "Max switching current", "dataType": "unit_value", "unit": "A", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "max_switching_voltage", "labelKo": "최대 개폐 전압", "labelEn": "Max switching voltage", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "operating_temp", "labelKo": "사용 온도", "labelEn": "Working temperature", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "weight_g", "labelKo": "중량", "labelEn": "Weight", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}]'::jsonb)
