insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-resistive-level-sensors', '저항식 레벨 센서', 'Resistive Level Sensors', '스템 내부의 리드 스위치 체인과 저항 네트워크로 유체 레벨을 연속적으로 측정하는 저항 출력형 레벨 센서입니다. 연료 게이지 등 레벨 인디케이터 구동에 적합하며 10/20mm 분해능을 제공합니다.', 'Resistive-output level sensors that measure fluid level continuously via a reed switch chain and resistor network inside the stem. Suitable for driving level gauges (e.g. fuel gauges) with 10/20 mm resolution.', (select id from business_areas where slug = 'hydraulic-engineering'), 150, '[{"key": "fixing", "labelKo": "고정 방식", "labelEn": "Fixing", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "stem_material", "labelKo": "스템 재질", "labelEn": "Stem material", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "float_material", "labelKo": "플로트 재질", "labelEn": "Float material", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "output_signal", "labelKo": "출력 신호", "labelEn": "Output signal", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "resistance_range", "labelKo": "저항 범위", "labelEn": "Resistance range", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "resolution_pitch", "labelKo": "분해능(피치)", "labelEn": "Resolution (pitch)", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "length_range", "labelKo": "길이 범위", "labelEn": "Length range", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "protection_rating", "labelKo": "보호 등급", "labelEn": "Protection degree", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "min_specific_gravity", "labelKo": "최소 유체 비중", "labelEn": "Min fluid specific gravity", "dataType": "number", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "operating_temp", "labelKo": "사용 온도", "labelEn": "Working temperature", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "media", "labelKo": "적용 유체", "labelEn": "Media", "dataType": "text", "required": false, "sortOrder": 11, "showInCardTeaser": false}, {"key": "stabilized_room", "labelKo": "안정화 챔버", "labelEn": "Stabilized room", "dataType": "boolean", "required": false, "sortOrder": 12, "showInCardTeaser": false}]'::jsonb)
