insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-temperature-accessories', '온도 센서 액세서리', 'Temperature Sensor Accessories', '온도 센서 설치용 액세서리로, 유체 누출 없이 센서를 탈착할 수 있게 해주는 보호관(써모웰) 등이 포함됩니다.', 'Installation accessories for temperature sensors, including thermowells that allow sensor removal without fluid leakage.', (select id from business_areas where slug = 'hydraulic-engineering'), 160, '[{"key": "model_variants", "labelKo": "모델 구성", "labelEn": "Model Variants", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "material", "labelKo": "재질", "labelEn": "Material", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "sensor_connection", "labelKo": "센서 측 접속", "labelEn": "Sensor-side Connection", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "overall_length", "labelKo": "전체 길이", "labelEn": "Overall Length", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "well_bore_diameter_mm", "labelKo": "보호관 외경", "labelEn": "Well Diameter", "dataType": "unit_value", "unit": "mm", "required": false, "sortOrder": 6, "showInCardTeaser": false}]'::jsonb)
