insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-temperature-sensors', '온도 센서 / 프로브', 'Temperature Sensors / Probes', 'NTC·PTC 서미스터, PT100·PT1000, KTY, Ni1000 등 다양한 감지 소자를 적용한 접촉식 온도 센서 시리즈입니다. 수지 몰딩형, 금속 캡슐형, 나사 체결형 등 여러 구조와 폭넓은 나사·커넥터 옵션을 제공합니다.', 'Contact-type temperature sensor series using NTC/PTC thermistors, PT100/PT1000, KTY and Ni1000 elements. Available as resin-moulded probes, metal-encapsulated probes and threaded sensors with a wide range of threads and integrated connectors.', (select id from business_areas where slug = 'hydraulic-engineering'), 170, '[{"key": "sensor_element", "labelKo": "감지 소자", "labelEn": "Sensing Element", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "working_temperature_range", "labelKo": "사용 온도 범위", "labelEn": "Working Temperature Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical Connection", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "thermistor_coat", "labelKo": "소자 피복", "labelEn": "Thermistor Coat", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}]'::jsonb)
