insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-temperature-switches', '온도 스위치 (바이메탈 서모스탯)', 'Temperature Switches (Bimetallic Thermostats)', '바이메탈 방식의 스냅 액션 온도 스위치(서모스탯) 시리즈로, 설정 온도에서 접점이 개폐되어 냉각팬 제어, 과열 보호 등에 사용됩니다. 황동 바디(요청 시 스테인리스)와 다양한 나사 규격을 지원합니다.', 'Bimetallic snap-action temperature switches (thermostats) that open or close a contact at a preset temperature, used for fan control and overheating protection. Brass body (stainless steel on request) with a wide choice of thread connections.', (select id from business_areas where slug = 'hydraulic-engineering'), 180, '[{"key": "setting_temperature_range", "labelKo": "설정 온도 범위", "labelEn": "Setting Temperature Range", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact Type", "dataType": "select", "options": [{"value": "no_or_nc", "labelKo": "N.O. 또는 N.C.", "labelEn": "N.O. or N.C."}, {"value": "spdt", "labelKo": "SPDT(교환 접점)", "labelEn": "SPDT (changeover)"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "switching_differential", "labelKo": "동작 편차(디퍼렌셜)", "labelEn": "Switching Differential", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical Connection", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "max_pressure_bar", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "max_ambient_temperature_c", "labelKo": "최대 주위 온도", "labelEn": "Max Ambient Temperature", "dataType": "unit_value", "unit": "°C", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "number_of_cycles", "labelKo": "동작 수명(사이클)", "labelEn": "Number of Cycles", "dataType": "number", "required": false, "sortOrder": 10, "showInCardTeaser": false}]'::jsonb)
