insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-temperature-transmitters', '온도 트랜스미터 / 전자식 온도 센서', 'Temperature Transmitters / Electronic Temperature Sensors', '4-20 mA 아날로그 출력, IO-Link, PWM 등 전자식 출력 신호를 제공하는 온도 트랜스미터 시리즈입니다. 일부 모델은 SCD 프로그래머로 설정 가능한 2개의 디지털(PNP) 출력을 갖추고 있습니다.', 'Electronic temperature transmitters with 4-20 mA analogue, IO-Link or PWM output signals. Some models feature two programmable PNP digital outputs configurable via the SCD programming device.', (select id from business_areas where slug = 'hydraulic-engineering'), 190, '[{"key": "output_signal", "labelKo": "출력 신호", "labelEn": "Output Signal", "dataType": "select", "options": [{"value": "4_20_ma", "labelKo": "4-20 mA 아날로그", "labelEn": "4-20 mA analogue"}, {"value": "io_link", "labelKo": "IO-Link", "labelEn": "IO-Link"}, {"value": "pwm", "labelKo": "PWM", "labelEn": "PWM"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "fluid_temperature_range", "labelKo": "유체 온도 범위", "labelEn": "Fluid Temperature Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "supply_voltage", "labelKo": "공급 전압", "labelEn": "Supply Voltage", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "max_pressure_bar", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": true}, {"key": "electrical_connection", "labelKo": "전기 접속", "labelEn": "Electrical Connection", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text