insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('euroswitch-vacuum-switches', '진공 스위치', 'Vacuum Switches', '설정 진공도(부압) 도달 시 전기 접점이 개폐되는 다이어프램식 진공 스위치입니다. 진공 이송, 흡착, 누설 감시 등 부압 감시 용도에 사용됩니다.', 'Diaphragm vacuum switches whose electric contacts switch when the set vacuum (negative pressure) is reached. Used for vacuum handling, suction and leak monitoring applications.', (select id from business_areas where slug = 'hydraulic-engineering'), 200, '[{"key": "setting_range", "labelKo": "설정 진공 범위", "labelEn": "Setting Range", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_working_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "overpressure_limit_bar", "labelKo": "최대 안전 압력", "labelEn": "Overpressure Limit", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "contact_type", "labelKo": "접점 형식", "labelEn": "Contact Type", "dataType": "select", "options": [{"value": "spst_no_or_nc", "labelKo": "SPST NO 또는 NC", "labelEn": "SPST NO or NC"}, {"value": "spdt", "labelKo": "SPDT (절환 접점)", "labelEn": "SPDT (changeover)"}], "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_switching_voltage", "labelKo": "최대 개폐 전압", "labelEn": "Max Switching Voltage", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "process_connection", "labelKo": "프로세스 접속", "labelEn": "Process Connection", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "protection_class", "labelKo": "보호 등급", "labelEn": "Protection Class (IP)", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "max_media_temp_c", "labelKo": "최대 유체 온도", "labelEn": "Max Media Temperature", "dataType": "unit_value", "unit": "°C", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}]'::jsonb)
