insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('gemels-actuators-kits', '액추에이터 및 키트', 'Actuators & Kits', 'GEMELS 볼 밸브용 공압(스카치요크/랙&피니언) 및 전동 액추에이터와 잠금장치, 핸들, 리미트 스위치 등 밸브 액세서리 키트 제품군.', 'Pneumatic (scotch-yoke and rack & pinion) and electric actuators for GEMELS ball valves, plus valve accessory kits including locking devices, handles and limit switches.', (select id from business_areas where slug = 'hydraulic-engineering'), 210, '[{"key": "product_type", "labelKo": "제품 종류", "labelEn": "Product Type", "dataType": "select", "options": [{"value": "pneumatic_actuator", "labelKo": "공압 액추에이터", "labelEn": "Pneumatic Actuator"}, {"value": "electric_actuator", "labelKo": "전동 액추에이터", "labelEn": "Electric Actuator"}, {"value": "locking_device", "labelKo": "잠금장치", "labelEn": "Locking Device"}, {"value": "handle", "labelKo": "핸들", "labelEn": "Handle"}, {"value": "limit_switch", "labelKo": "리미트 스위치", "labelEn": "Limit Switch"}], "required": true, "sortOrder": 1, "showInCardTeaser": true}, {"key": "operation", "labelKo": "작동 방식", "labelEn": "Operation", "dataType": "select", "options": [{"value": "double_acting", "labelKo": "복동식", "labelEn": "Double Acting"}, {"value": "spring_return", "labelKo": "스프링 리턴", "labelEn": "Spring Return"}, {"value": "electric", "labelKo": "전동", "labelEn": "Electric"}, {"value": "manual", "labelKo": "수동", "labelEn": "Manual"}, {"value": "monitoring", "labelKo": "위치 감지", "labelEn": "Position Monitoring"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "models", "labelKo": "모델 구성", "labelEn": "Models", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "torque_range_nm", "labelKo": "토크 범위", "labelEn": "Torque Range", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "supply", "labelKo": "구동원", "labelEn": "Supply", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "iso5211_flange", "labelKo": "ISO 5211 플랜지", "labelEn": "ISO 5211 Flange", "dataType": "