insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('gemels-ball-valves', '볼 밸브', 'Ball Valves', 'GEMELS의 유압용 고압 볼 밸브 시리즈입니다. 2웨이/3웨이/4웨이 구성, DN6~DN125 사이즈, 최대 1,000bar 압력 등급을 갖추며 나사식(BSP/NPT/SAE/DIN 2353)과 플랜지식(SAE J518, ISO 6164), 매니폴드 장착형, 통합 퀵 커플링형 등 다양한 접속 방식을 제공합니다.', 'GEMELS high-pressure ball valves for the hydraulic field. Available in 2-way/3-way/4-way configurations, sizes DN6 to DN125 and pressure ratings up to 1,000 bar, with threaded (BSP/NPT/SAE/DIN 2353), flanged (SAE J518, ISO 6164), manifold-mounted and integrated quick-coupling connection options.', (select id from business_areas where slug = 'hydraulic-engineering'), 220, '[{"key": "valve_ways", "labelKo": "유로 수", "labelEn": "Number of Ways", "dataType": "select", "options": [{"value": "2_way", "labelKo": "2웨이", "labelEn": "2-way"}, {"value": "3_way", "labelKo": "3웨이", "labelEn": "3-way"}, {"value": "4_way", "labelKo": "4웨이", "labelEn": "4-way"}, {"value": "tandem", "labelKo": "탠덤(복합)", "labelEn": "Tandem (combination)"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "size_range", "labelKo": "사이즈 범위", "labelEn": "Size Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "max_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "body_material", "labelKo": "바디 재질", "labelEn": "Body Material", "dataType": "select", "options": [{"value": "carbon_steel", "labelKo": "탄소강", "labelEn": "Carbon steel"}, {"value": "stainless_steel", "labelKo": "스테인리스강", "labelEn": "Stainless steel"}, {"value": "carbon_or_stainless_steel", "labelKo": "탄소강/스테인리스강", "labelEn": "Carbon or stainless steel"}], "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "seat_material", "labelKo": "시트 재질", "labelEn": "Seat Material", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "seal_material", "labelKo": "실 재질", "labelEn": "Seal Material", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "port_types", "labelKo": "포트/접속 방식", "labelEn": "Port / Connection Types", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "temp_range", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "surface_treatment", "labelKo": "표면 처리", "labelEn": "Surface Treatment", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "special_features", "labelKo": "특징", "labelEn": "Special Features", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}]'::jsonb)
