insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('gemels-electric-motors', '전기 모터', 'Electric Motors', '이탈리아에서 설계·생산되는 GEMELS AC 3상 토크 모터 시리즈. 2~100 kW, 48~400V, 최대 10,000 RPM으로 견인 구동, 유압 파워 유닛, 표준 플랜지(IEC/NEMA) 응용에 대응합니다.', 'GEMELS series of AC three-phase torque motors designed and produced in Italy, from 2 to 100 kW, 48 to 400V and up to 10,000 RPM, for traction, hydraulic power units and standard IEC/NEMA flange applications.', (select id from business_areas where slug = 'hydraulic-engineering'), 230, '[{"key": "motor_type", "labelKo": "모터 형식", "labelEn": "Motor Type", "dataType": "text", "required": true, "sortOrder": 1, "showInCardTeaser": true}, {"key": "power_range_kw", "labelKo": "출력 범위", "labelEn": "Power Range", "dataType": "text", "required": true, "sortOrder": 2, "showInCardTeaser": true}, {"key": "voltage_range_v", "labelKo": "전압 범위", "labelEn": "Voltage Range", "dataType": "text", "required": true, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_speed_rpm", "labelKo": "최대 회전수", "labelEn": "Max Speed", "dataType": "unit_value", "unit": "RPM", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "cooling", "labelKo": "냉각 방식", "labelEn": "Cooling", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "mounting", "labelKo": "장착 방식", "labelEn": "Mounting", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "applications", "labelKo": "적용 분야", "labelEn": "Applications", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}]'::jsonb)
