insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('gemels-hydraulic-valves', '유압 밸브', 'Hydraulic Valves', '볼 밸브 외에 GEMELS가 공급하는 유압 밸브 제품군: 오버센터 밸브, 릴리프 밸브, 체크 밸브, 유량 제어/분배 밸브, 셔틀 밸브, 안전 밸브 블록 등. 농기계, 자동차, 조선, 소방, 제철 등 다양한 산업에 적용됩니다.', 'GEMELS hydraulic valve range beyond ball valves: overcenter valves, relief valves, check valves, flow control/diverter valves, shuttle valves and accumulator safety valve blocks, serving agriculture, automotive, naval, firefighting, steel plants and more.', (select id from business_areas where slug = 'hydraulic-engineering'), 240, '[{"key": "valve_type", "labelKo": "밸브 종류", "labelEn": "Valve Type", "dataType": "select", "options": [{"value": "safety_valve", "labelKo": "안전 밸브", "labelEn": "Safety Valve"}, {"value": "overcenter_valve", "labelKo": "오버센터 밸브", "labelEn": "Overcenter Valve"}, {"value": "relief_valve", "labelKo": "릴리프 밸브", "labelEn": "Relief Valve"}, {"value": "check_valve", "labelKo": "체크 밸브", "labelEn": "Check Valve"}, {"value": "pilot_check_valve", "labelKo": "파일럿 체크 밸브", "labelEn": "Pilot Operated Check Valve"}, {"value": "flow_control_valve", "labelKo": "유량 제어 밸브", "labelEn": "Flow Control Valve"}, {"value": "flow_regulator", "labelKo": "유량 조절기", "labelEn": "Flow Regulator"}, {"value": "shuttle_valve", "labelKo": "셔틀 밸브", "labelEn": "Shuttle Valve"}, {"value": "hose_break_valve", "labelKo": "호스 파단 밸브", "labelEn": "Hose Break Valve"}, {"value": "flow_diverter", "labelKo": "유량 분배 밸브", "labelEn": "Flow Diverter"}], "required": true, "sortOrder": 1, "showInCardTeaser": true}, {"key": "size_range", "labelKo": "사이즈 범위", "labelEn": "Size Range", "dataType": "text", "required": true, "sortOrder": 2, "showInCardTeaser": true}, {"key": "max_pressure_mpa", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "MPa", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "end_connections", "labelKo": "접속 규격", "labelEn": "End Connections", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "본체 재질", "labelEn": "Body Material", "dataType": "select", "options": [{"value": "carbon_steel", "labelKo": "탄소강", "labelEn": "Carbon Steel"}, {"value": "stainless_steel", "labelKo": "스테인리스강", "labelEn": "Stainless Steel"}, {"value": "carbon_or_stainless_steel", "labelKo": "탄소강/스테인리스강", "labelEn": "Carbon or Stainless Steel"}, {"value": "cast_iron", "labelKo": "주철", "labelEn": "Cast Iron"}], "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "temp_range_c", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max Flow", "dataType": "unit_value", "unit": "l/min", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "seal_material", "labelKo": "시일 재질", "labelEn": "Seal Material", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "surface_treatment", "labelKo": "표면 처리", "labelEn": "Surface Treatment", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}]'::jsonb)
