insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('gemels-oil-gas-ball-valves', '오일&가스 볼 밸브', 'Oil & Gas Ball Valves', '플로팅 및 트러니언 설계의 오일&가스용 볼 밸브. 1/4"~42" 사이즈, ANSI 150~2500 클래스, 온쇼어/오프쇼어의 업스트림·미드스트림·다운스트림 분야 국제 규격(API 6D 등)에 부합합니다.', 'Floating and trunnion design ball valves for oil & gas, from 1/4" up to 42", ANSI class 150-2500, compliant with international norms (API 6D etc.) for onshore/offshore upstream, midstream and downstream applications.', (select id from business_areas where slug = 'hydraulic-engineering'), 250, '[{"key": "valve_design", "labelKo": "밸브 설계", "labelEn": "Valve Design", "dataType": "select", "options": [{"value": "floating_screwed", "labelKo": "플로팅(나사식)", "labelEn": "Floating (Screwed Ends)"}, {"value": "floating_high_cyclicity", "labelKo": "플로팅(고빈도 작동)", "labelEn": "Floating (High Cyclicity)"}, {"value": "wafer_floating", "labelKo": "웨이퍼 플로팅", "labelEn": "Wafer Type Floating"}, {"value": "split_body_floating", "labelKo": "스플릿 바디 플로팅", "labelEn": "Split Body Floating"}, {"value": "split_body_trunnion", "labelKo": "스플릿 바디 트러니언", "labelEn": "Split Body Trunnion"}, {"value": "double_block_bleed", "labelKo": "더블 블록 앤 블리드", "labelEn": "Double Block and Bleed"}], "required": true, "sortOrder": 1, "showInCardTeaser": true}, {"key": "size_range", "labelKo": "사이즈 범위", "labelEn": "Size Range", "dataType": "text", "required": true, "sortOrder": 2, "showInCardTeaser": true}, {"key": "pressure_class", "labelKo": "압력 클래스", "labelEn": "Pressure Class", "dataType": "text", "required": true, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_pressure_mpa", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "MPa", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "end_connections", "labelKo": "접속 규격", "labelEn": "End Connections", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "본체 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "temp_range_c", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "standards", "labelKo": "적용 규격", "labelEn": "Standards", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "iso5211_mount", "labelKo": "ISO 5211 액추에이터 마운트", "labelEn": "ISO 5211 Actuator Mount", "dataType": "boolean", "required": false, "sortOrder": 9, "showInCardTeaser": false}]'::jsonb)
