: "탄소강", "labelEn": "Carbon steel"}, {"value": "stainless_steel", "labelKo": "스테인리스강", "labelEn": "Stainless steel"}, {"value": "carbon_or_stainless_steel", "labelKo": "탄소강 / 스테인리스강", "labelEn": "Carbon or stainless steel"}, {"value": "carbon_stainless_or_brass", "labelKo": "탄소강 / 스테인리스강 / 황동", "labelEn": "Carbon steel / stainless steel / brass"}], "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "valve_type", "labelKo": "밸브 방식", "labelEn": "Valve Type", "dataType": "select", "options": [{"value": "flat_face", "labelKo": "플랫 페이스", "labelEn": "Flat face"}, {"value": "poppet", "labelKo": "포핏", "labelEn": "Poppet"}, {"value": "ball", "labelKo": "볼", "labelEn": "Ball"}, {"value": "ball_shutoff", "labelKo": "볼 밸브 차단식", "labelEn": "Ball-valve shut-off"}], "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "connection_type", "labelKo": "체결 방식", "labelEn": "Connection Type", "dataType": "select", "options": [{"value": "push_pull_sleeve", "labelKo": "푸시풀 슬리브", "labelEn": "Push-pull sleeve"}, {"value": "screw_to_connect", "labelKo": "스크류 체결식", "labelEn": "Screw-to-connect"}, {"value": "plate_mounting", "labelKo": "플레이트 마운팅", "labelEn": "Plate mounting"}, {"value": "multi_plate", "labelKo": "멀티 커플링 플레이트", "labelEn": "Multi-coupling plate"}, {"value": "quick_interlock", "labelKo": "퀵 인터록", "labelEn": "Quick interlock"}], "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "connect_under_pressure", "labelKo": "잔압 연결 가능", "labelEn": "Connectable Under Residual Pressure", "dataType": "boolean", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "seal_material", "labelKo": "씰 재질", "labelEn": "Seal Material", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "thread_types", "labelKo": "연결 나사 규격", "labelEn": "End Thread Types", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "surface_treatment", "labelKo": "표면 처리", "labelE