values ('moveco-arl-series', 'ARL 시리즈 로터리 액추에이터 (산업용 밸브 구동)', 'ARL Series Rotary Actuators (Industrial Valve Actuation)', '산업용 볼 밸브·버터플라이 밸브 등 쿼터턴(90°) 밸브 구동을 위한 헬리컬 로터리 액추에이터 시리즈입니다. 개폐(Open/Shut) 동작 사양도 요청 시 제작 가능합니다.', 'Helical rotary actuators for quarter-turn (90-degree) actuation of industrial valves such as ball and butterfly valves. Open/shut workable versions are available on request.', (select id from business_areas where slug = 'hydraulic-engineering'), 300, '[{"key": "torque_active", "labelKo": "작동 토크 (210 bar)", "labelEn": "Active Torque (210 bar)", "dataType": "unit_value", "unit": "Nm", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "working_pressure", "labelKo": "작동 압력 범위", "labelEn": "Working Pressure Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "rotation_angle", "labelKo": "회전 각도", "labelEn": "Rotation Angle", "dataType": "unit_value", "unit": "°", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "displacement", "labelKo": "용적 (90°)", "labelEn": "Displacement (90°)", "dataType": "unit_value", "unit": "cm³", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "weight", "labelKo": "중량 (약)", "labelEn": "Approximate Weight", "dataType": "unit_value", "unit": "kg", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "ports", "labelKo": "표준 포트 규격", "labelEn": "Standard Ports", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}]'::jsonb)
