ar", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "weight_kg", "labelKo": "중량 (kg)", "labelEn": "Weight (kg)", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}]'::jsonb)
