ure_bar", "labelKo": "최대 압력", "labelEn": "Max pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "adjustment", "labelKo": "조절 방식", "labelEn": "Adjustment", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "pilot_ratio", "labelKo": "파일럿 비율", "labelEn": "Pilot ratio", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "cracking_pressure", "labelKo": "크래킹 압력(스프링)", "labelEn": "Cracking pressure (spring)", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "seal_material", "labelKo": "시일 재질", "labelEn": "Seal material", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "controlled_flow_range", "labelKo": "제어 유량 범위", "labelEn": "Controlled flow range", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "thread", "labelKo": "나사 규격", "labelEn": "Thread", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "setting_range_bar", "labelKo": "설정 압력 범위 (bar)", "labelEn": "Setting Range (bar)", "dataType": "text", "required": false, "sortOrder": 11, "showInCardTeaser": false}, {"key": "tightening_torque_nm", "labelKo": "조임 토크 (Nm)", "labelEn": "Tightening Torque (Nm)", "dataType": "text", "required": false, "sortOrder": 12, "showInCardTeaser": false}, {"key": "weight_kg", "labelKo": "중량 (kg)", "labelEn": "Weight (kg)", "dataType": "text", "required": false, "sortOrder": 13, "showInCardTeaser": false}]'::jsonb)
