r": false}, {"key": "operation", "labelKo": "조작 방식", "labelEn": "Operation", "dataType": "select", "options": [{"value": "manual", "labelKo": "수동 조작", "labelEn": "Manual operated"}, {"value": "lever", "labelKo": "레버 조작", "labelEn": "Lever operated"}, {"value": "pneumatic", "labelKo": "공압 조작", "labelEn": "Pneumatic operated"}, {"value": "single_po", "labelKo": "싱글 파일럿", "labelEn": "Single PO"}, {"value": "double_po", "labelKo": "더블 파일럿", "labelEn": "Double PO"}], "required": false, "showInCardTeaser": true, "sortOrder": 9}, {"key": "execution", "labelKo": "구조 형식", "labelEn": "Execution", "dataType": "select", "options": [{"value": "cartridge", "labelKo": "카트리지", "labelEn": "Cartridge"}, {"value": "parts_in_body", "labelKo": "바디 일체형", "labelEn": "Parts in body"}], "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "installation", "labelKo": "설치 방식", "labelEn": "Installation", "dataType": "select", "options": [{"value": "screwed_in", "labelKo": "나사 삽입형", "labelEn": "Screwed-in"}, {"value": "in_line", "labelKo": "인라인", "labelEn": "In-line"}, {"value": "flanged", "labelKo": "플랜지형", "labelEn": "Flanged"}], "required": false, "sortOrder": 11, "showInCardTeaser": true}, {"key": "variant_codes", "labelKo": "포함 모델 코드", "labelEn": "Series Variant Codes", "dataType": "text", "required": false, "sortOrder": 12, "showInCardTeaser": false}]'::jsonb)
