dknob"}, {"value": "fixed", "labelKo": "고정 설정", "labelEn": "Fixed Setting"}], "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "execution", "labelKo": "구조 형식", "labelEn": "Execution", "dataType": "select", "options": [{"value": "cartridge", "labelKo": "카트리지", "labelEn": "Cartridge"}, {"value": "parts_in_body", "labelKo": "바디 일체형", "labelEn": "Parts in body"}], "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "installation", "labelKo": "설치 방식", "labelEn": "Installation", "dataType": "select", "options": [{"value": "screwed_in", "labelKo": "나사 삽입형", "labelEn": "Screwed-in"}, {"value": "in_line", "labelKo": "인라인", "labelEn": "In-line"}, {"value": "flanged", "labelKo": "플랜지형", "labelEn": "Flanged"}], "required": false, "sortOrder": 9, "showInCardTeaser": true}, {"key": "variant_codes", "labelKo": "포함 모델 코드", "labelEn": "Series Variant Codes", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}]'::jsonb)
