insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('oleoweb-safety-valves', '배관 안전 밸브', 'Hose Burst Safety Valves', '호스/배관 파손 시 유량 급증을 감지하여 자동 차단함으로써 하중의 자유 낙하를 방지하는 배관 안전(호스 파열 방지) 밸브입니다.', 'Hose burst (pipe safety) valves that automatically shut off when excess flow from a burst hose or pipe is detected, preventing uncontrolled load fall.', (select id from business_areas where slug = 'hydraulic-engineering'), 460, '[{"key": "max_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "port_sizes", "labelKo": "포트 사이즈", "labelEn": "Port Sizes", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "connection_standard", "labelKo": "접속 규격", "labelEn": "Connection Standard", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "setting_range", "labelKo": "차단 유량 설정 범위", "labelEn": "Trip Flow Setting Range", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "orifice_option", "labelKo": "포핏 오리피스 옵션", "labelEn": "Poppet Orifice Option", "dataType": "boolean", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "mounting_style", "labelKo": "장착 방식", "labelEn": "Mounting Style", "dataType": "select", "options": [{"value": "insert", "labelKo": "인서트(카트리지)", "labelEn": "Insert (Cartridge)"}, {"value": "in_line", "labelKo": "인라인", "labelEn": "In-line"}], "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "max_leakage", "labelKo": "최대 누유량", "labelEn": "Max Leakage", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}]'::jsonb)
