insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('oleoweb-shock-valves', '안티쇼크 밸브 (더블 크로스 릴리프)', 'Anti-Shock Valves (Dual Cross-Line Relief)', '유압 모터 회로의 압력 서지를 양방향으로 흡수하는 더블 크로스 라인 직동형 릴리프 밸브입니다. 인라인 블록형과 OMP/OMR/OMS 모터 직결 플랜지형을 포함합니다.', 'Double cross-line direct acting relief valves absorbing pressure shocks in both directions of hydraulic motor circuits. Available as in-line blocks and flange-mounted versions for OMP/OMR/OMS motors.', (select id from business_areas where slug = 'hydraulic-engineering'), 470, '[{"key": "max_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "port_sizes", "labelKo": "포트 사이즈", "labelEn": "Port Sizes", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "setting_ranges", "labelKo": "설정 압력 범위(스프링)", "labelEn": "Setting Ranges (Springs)", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "mounting_style", "labelKo": "장착 방식", "labelEn": "Mounting Style", "dataType": "select", "options": [{"value": "in_line", "labelKo": "인라인 블록", "labelEn": "In-line Block"}, {"value": "motor_flange", "labelKo": "모터 플랜지", "labelEn": "Motor Flange"}], "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "motor_compatibility", "labelKo": "적용 모터", "labelEn": "Motor Compatibility", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "relief_cartridge", "labelKo": "릴리프 카트리지", "labelEn": "Relief Cartridge", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}]'::jsonb)
