insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('oleoweb-solenoid-valves', '솔레노이드 밸브', 'Solenoid Valves', 'SAE 카트리지 캐비티용 전기 작동(솔레노이드) 밸브. 직동식·파일럿 작동식 2웨이/2포지션 포핏 밸브, 3웨이 스풀 밸브, 4웨이 3포지션 ON-OFF 및 전자비례 유량 제어 밸브를 포함하며 12/24 VDC, 220 VAC 코일과 DIN·Deutsch 커넥터를 지원합니다.', 'Electrically operated (solenoid) valves for SAE cartridge cavities: direct-acting and pilot-operated 2-way/2-position poppet valves, 3-way spool valves, 4-way 3-position on-off and electro-proportional flow control valves. Coils available in 12/24 VDC and 220 VAC with DIN and Deutsch connectors.', (select id from business_areas where slug = 'hydraulic-engineering'), 480, '[{"key": "valve_function", "labelKo": "밸브 기능", "labelEn": "Valve function", "dataType": "select", "options": [{"value": "2_2", "labelKo": "2웨이/2포지션", "labelEn": "2-way/2-position"}, {"value": "3_2", "labelKo": "3웨이/2포지션", "labelEn": "3-way/2-position"}, {"value": "4_3", "labelKo": "4웨이/3포지션", "labelEn": "4-way/3-position"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "actuation", "labelKo": "작동 방식", "labelEn": "Actuation", "dataType": "select", "options": [{"value": "direct_acting", "labelKo": "직동식", "labelEn": "Direct acting"}, {"value": "pilot_operated", "labelKo": "파일럿 작동식", "labelEn": "Pilot operated"}, {"value": "proportional", "labelKo": "전자비례식", "labelEn": "Electro-proportional"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "circuit_options", "labelKo": "회로 구성", "labelEn": "Circuit options", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": false}, {"key": "cavity", "labelKo": "캐비티", "labelEn": "Cavity", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 5, "showInCardTeaser": true}, {"key": "max_pressure_bar", "labelKo": "최대 압력", "labelEn": "Max pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "voltage_options", "labelKo": "코일 전압", "labelEn": "Coil voltages", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "coil_power", "labelKo": "코일 소비 전력", "labelEn": "Coil power", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "manual_override", "labelKo": "수동(비상) 조작", "labelEn": "Manual override", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "seal_material", "labelKo": "시일 재질", "labelEn": "Seal material", "dataType": "text", "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "valve_type", "labelKo": "밸브 타입", "labelEn": "Valve Type", "dataType": "select", "options": [{"value": "check_2_2", "labelKo": "2/2 체크", "labelEn": "2/2 check"}, {"value": "check_2_2_double_sealing", "labelKo": "2/2 더블 실링 체크", "labelEn": "2/2 check, double sealing"}, {"value": "spool_3_2", "labelKo": "3/2 스풀", "labelEn": "3/2 spool"}, {"value": "spool_4_3", "labelKo": "4/3 스풀", "labelEn": "4/3 spool"}], "required": false, "showInCardTeaser": true, "sortOrder": 11}, {"key": "execution", "labelKo": "구조 형식", "labelEn": "Execution", "dataType": "select", "options": [{"value": "cartridge", "labelKo": "카트리지", "labelEn": "Cartridge"}], "required": false, "sortOrder": 12, "showInCardTeaser": false}, {"key": "installation", "labelKo": "설치 방식", "labelEn": "Installation", "dataType": "select", "options": [{"value": "screwed_in", "labelKo": "나사 삽입형", "labelEn": "Screwed-in"}], "required": false, "sortOrder": 13, "showInCardTeaser": true}, {"key": "variant_codes", "labelKo": "포함 모델 코드", "labelEn": "Series Variant Codes", "dataType": "text", "required": false, "sortOrder": 14, "showInCardTeaser": false}]'::jsonb)
