values ('water-hydraulics-check-valves', '체크·안전 밸브', 'Check & Safety Valves', '316 스테인리스강 Janus 체크 밸브와 호스 파열 방지 밸브. 장기간 미사용 후에도 일관된 성능을 제공합니다.', 'Janus check valves and hose burst valves in 316 stainless steel, delivering consistent performance even after long periods of inactivity.', (select id from business_areas where slug = 'fluid-gas'), 510, '[{"key": "valve_type", "labelKo": "밸브 타입", "labelEn": "Valve Type", "dataType": "select", "options": [{"value": "check", "labelKo": "체크 밸브", "labelEn": "Check valve"}, {"value": "hose_burst", "labelKo": "호스 파열 방지 밸브", "labelEn": "Hose burst valve"}, {"value": "pilot_operated_check", "labelKo": "pilot_operated_check", "labelEn": "pilot_operated_check"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "nominal_size", "labelKo": "호칭 크기", "labelEn": "Nominal Size", "dataType": "select", "options": [{"value": "dn3", "labelKo": "DN3", "labelEn": "DN3"}, {"value": "dn6", "labelKo": "DN6", "labelEn": "DN6"}, {"value": "dn9", "labelKo": "DN9", "labelEn": "DN9"}, {"value": "dn12", "labelKo": "DN12", "labelEn": "DN12"}, {"value": "dn16", "labelKo": "DN16", "labelEn": "DN16"}, {"value": "dn25", "labelKo": "DN25", "labelEn": "DN25"}, {"value": "1/4\" BSP (피드 갤러리 6mm/4mm)", "labelKo": "1/4\" BSP (피드 갤러리 6mm/4mm)", "labelEn": "1/4\" BSP (피드 갤러리 6mm/4mm)"}, {"value": "DN12 (피드 갤러리 12mm)", "labelKo": "DN12 (피드 갤러리 12mm)", "labelEn": "DN12 (피드 갤러리 12mm)"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "pressure_range", "labelKo": "압력 범위", "labelEn": "Pressure Range", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "cv_value", "labelKo": "Cv 값", "labelEn": "Cv Value", "dataType": "number", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "max_flow_lpm", "labelKo": "최대 유량", "labelEn": "Max Flow", "dataType": "unit_value", "unit": "L/min", "required": false, "sortOrder": 5, "showInCardTeaser": true}, {"key": "porting", "labelKo": "포트