values ('water-hydraulics-cylinders', '스테인리스 실린더', 'Stainless Steel Cylinders', '타이로드 구조의 Janus 전 스테인리스(316) 워터 하이드로릭 실린더. 단동/복동형, 다양한 로드 엔드와 마운팅 옵션을 제공합니다.', 'Janus all-stainless (316) tie-rod water hydraulic cylinders, single or double acting, with a range of rod ends and mounting options.', (select id from business_areas where slug = 'fluid-gas'), 520, '[{"key": "bore_range", "labelKo": "보어 크기", "labelEn": "Bore Range", "dataType": "text", "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "rod_diameter_range", "labelKo": "로드 직경", "labelEn": "Rod Diameter Range", "dataType": "text", "required": false, "sortOrder": 2, "showInCardTeaser": false}, {"key": "stroke_range", "labelKo": "스트로크 범위", "labelEn": "Stroke Range", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_pressure_bar", "labelKo": "최대 압력", "labelEn": "Max Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "max_speed", "labelKo": "최대 속도", "labelEn": "Max Speed", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "action", "labelKo": "작동 방식", "labelEn": "Action", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": true}, {"key": "mounting_options", "labelKo": "마운팅 옵션", "labelEn": "Mounting Options", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}, {"key": "port_size", "labelKo": "포트 크기", "labelEn": "Port Size", "dataType": "text", "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "body_material", "labelKo": "본체 재질", "labelEn": "Body Material", "dataType": "text", "required": false, "sortOrder": 9, "showInCardTeaser": false}]'::jsonb)
