insert into product_categories (slug, name_ko, name_en, description_ko, description_en, business_area_id, sort_order, spec_schema)
values ('water-hydraulics-directional-valves', '방향 제어 밸브', 'Directional Control Valves', '수돗물(EU 98/83/EC)용 Janus 방향 제어 밸브. 4/3, 4/2, 3/2, 2/2 기능과 솔레노이드·수동·파일럿·스테퍼 모터 구동을 지원하며 316 스테인리스강/폴리머 구조입니다.', 'Janus directional control valves for tap water to EU 98/83/EC. 4/3, 4/2, 3/2 and 2/2 functions with solenoid, manual, pilot or stepper-motor actuation, built in 316 stainless steel and polymer.', (select id from business_areas where slug = 'fluid-gas'), 540, '[{"key": "valve_function", "labelKo": "밸브 기능", "labelEn": "Valve Function", "dataType": "select", "options": [{"value": "4_3", "labelKo": "4/3 밸브", "labelEn": "4/3 valve"}, {"value": "4_2", "labelKo": "4/2 밸브", "labelEn": "4/2 valve"}, {"value": "3_2", "labelKo": "3/2 밸브", "labelEn": "3/2 valve"}, {"value": "2_2", "labelKo": "2/2 밸브", "labelEn": "2/2 valve"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "actuation", "labelKo": "구동 방식", "labelEn": "Actuation", "dataType": "select", "options": [{"value": "solenoid", "labelKo": "솔레노이드", "labelEn": "Solenoid"}, {"value": "manual", "labelKo": "수동", "labelEn": "Manual"}, {"value": "pilot", "labelKo": "파일럿", "labelEn": "Pilot"}, {"value": "stepper_motor", "labelKo": "스테퍼 모터", "labelEn": "Stepper motor"}], "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "nominal_size", "labelKo": "호칭 크기", "labelEn": "Nominal Size", "dataType": "select", "options": [{"value": "dn3", "labelKo": "DN3", "labelEn": "DN3"}, {"value": "dn6", "labelKo": "DN6", "labelEn": "DN6"}, {"value": "dn9", "labelKo": "DN9", "labelEn": "DN9"}, {"value": "dn16", "labelKo": "DN16", "labelEn": "DN16"}, {"value": "dn25", "labelKo": "DN25", "labelEn": "DN25"}], "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "max_inlet_pressure_bar", "labelKo": "최대 입구 압력", "labelEn": "Max Inlet Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 4, "showInCardTeaser": true}, {"key": "operating_pressure_range", "labelKo": "사용 압력 범