values ('water-hydraulics-filtration', '여과 시스템', 'Filtration', '워터 하이드로릭 시스템용 필터 하우징, 고압 인라인 필터, 카트리지 및 스테인리스 필터 엘리먼트입니다.', 'Filter housings, high-pressure in-line filters, cartridges and stainless steel filter elements for water hydraulic systems.', (select id from business_areas where slug = 'fluid-gas'), 550, '[{"key": "filter_type", "labelKo": "필터 유형", "labelEn": "Filter Type", "dataType": "select", "options": [{"value": "housing", "labelKo": "필터 하우징", "labelEn": "Filter housing"}, {"value": "high_pressure_filter", "labelKo": "고압 필터", "labelEn": "High pressure filter"}, {"value": "cartridge", "labelKo": "카트리지", "labelEn": "Cartridge"}, {"value": "element", "labelKo": "필터 엘리먼트", "labelEn": "Filter element"}], "required": false, "sortOrder": 1, "showInCardTeaser": true}, {"key": "max_pressure_bar", "labelKo": "최대 사용 압력", "labelEn": "Max Working Pressure", "dataType": "unit_value", "unit": "bar", "required": false, "sortOrder": 2, "showInCardTeaser": true}, {"key": "micron_ratings", "labelKo": "여과 등급", "labelEn": "Micron Ratings", "dataType": "text", "required": false, "sortOrder": 3, "showInCardTeaser": true}, {"key": "port_size", "labelKo": "포트 크기", "labelEn": "Port Size", "dataType": "text", "required": false, "sortOrder": 4, "showInCardTeaser": false}, {"key": "temperature_range", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 5, "showInCardTeaser": false}, {"key": "material", "labelKo": "재질", "labelEn": "Material", "dataType": "text", "required": false, "sortOrder": 6, "showInCardTeaser": false}, {"key": "flow_note", "labelKo": "유량 특성", "labelEn": "Flow Note", "dataType": "text", "required": false, "sortOrder": 7, "showInCardTeaser": false}]'::jsonb)
