, {"value": "fire_pump", "labelKo": "소방(미스트)용", "labelEn": "Fire / water-mist pump"}], "required": false, "sortOrder": 8, "showInCardTeaser": false}, {"key": "inlet_type", "labelKo": "흡입 구성", "labelEn": "Inlet Configuration", "dataType": "select", "options": [{"value": "unboosted_2port", "labelKo": "2포트 비가압(언부스티드)", "labelEn": "2-port unboosted"}, {"value": "boosted_3port", "labelKo": "3포트 가압(부스티드)", "labelEn": "3-port boosted"}, {"value": "both", "labelKo": "2포트/3포트 선택", "labelEn": "Unboosted or boosted"}], "required": false, "sortOrder": 9, "showInCardTeaser": false}, {"key": "material", "labelKo": "주요 재질", "labelEn": "Material", "dataType": "select", "options": [{"value": "stainless_316", "labelKo": "스테인리스 316", "labelEn": "316 stainless steel"}, {"value": "stainless_316l", "labelKo": "스테인리스 316L", "labelEn": "316L stainless steel"}], "required": false, "sortOrder": 10, "showInCardTeaser": false}, {"key": "temp_range", "labelKo": "사용 온도 범위", "labelEn": "Temperature Range", "dataType": "text", "required": false, "sortOrder": 11, "showInCardTeaser": false}, {"key": "atex", "labelKo": "ATEX 승인", "labelEn": "ATEX Approved", "dataType": "boolean", "required": false, "sortOrder": 12, "showInCardTeaser": false}, {"key": "displacement_max_cc", "labelKo": "최대 배기량", "labelEn": "Max Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 13, "showInCardTeaser": true}, {"key": "displacement_min_cc", "labelKo": "최소 배기량", "labelEn": "Min Displacement", "dataType": "unit_value", "unit": "cc/rev", "required": false, "sortOrder": 14, "showInCardTeaser": false}, {"key": "max_speed_rpm", "labelKo": "최대 회전수 (비부스트)", "labelEn": "Max Speed (unboosted)", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 15, "showInCardTeaser": false}, {"key": "boosted_speed_rpm", "labelKo": "최대 회전수 (부스트)", "labelEn": "Max Speed (boosted)", "dataType": "unit_value", "unit": "rpm", "required": false, "sortOrder": 16, "showInCardTeaser": false}, {"